cd /tmp && node -e "
const Database = require('better-sqlite3');
const crypto = require('crypto');
const db = new Database('/workspace/world.db');

// Existing reminder values
const content = \"Follow up with Maya if she's not there by 6:30 PM.\";
const reminderTimestamp = 1788269400;
const latitude = 37.7749;
const longitude = -122.4194;
const now = Math.floor(Date.now() / 1000);
const newId = crypto.randomUUID();

db.prepare(
  'INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude, created_at) VALUES (?, ?, ?, ?, ?, ?, datetime(?, \"unixepoch\"))'
).run(newId, content, now, reminderTimestamp, latitude, longitude, now);

// Verify
const row = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(newId);
console.log(JSON.stringify(row, null, 2));
"

