const newId = crypto.randomUUID();
const createdAt = new Date(now * 1000).toISOString().replace('T', 'T').slice(0, 19);

db.prepare(
  'INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)'
).run(newId, content, now, reminderTimestamp, latitude, longitude, createdAt);

// Verify
const row = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(newId);
console.log(JSON.stringify(row, null, 2));
